/** Inline SVG for a glyph. size defaults to 20; the stroke stays 1.5 px at 24 and scales with the box. */
window.glyph = function (name, size = 20, group) {
  const g = (group ? window.GLYPHS[group] : null)?.[name] ?? window.GLYPHS.actions[name] ?? window.GLYPHS.modules[name];
  if (!g) return "";
  return `<svg class="glyph" width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${g.d}</svg>`;
};

/** Replace every <i data-g="name" data-s="size"> with its SVG. */
window.renderGlyphs = function (root = document) {
  root.querySelectorAll("i[data-g]").forEach((el) => {
    el.outerHTML = window.glyph(el.dataset.g, Number(el.dataset.s || 20), el.dataset.group);
  });
};
